INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118061, 91002, 2, 10118, 40, 2834, 0, 7, 20063115, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 1, "青空の下で謁見", "ペコリーヌとの出会い", 8, "フリーマーケット会場");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118062, 91002, 2, 10118, 40, 2835, 0, 7, 20063115, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 1, "未来の騎空団\nマスコット？", "マホとの出会い", 8, "フリーマーケット会場");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118063, 91002, 2, 10118, 40, 2837, 0, 7, 20063115, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 1, "お嬢さまからの\n緊急依頼", "アキノとの出会い", 8, "ランドソル市街地");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118064, 91002, 2, 10118, 40, 4108402, 0, 18, 20063115, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 1, "黄金色の悩みごと", "ジュンとの出会い", 8, "フリーマーケット会場");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118065, 91002, 2, 10118, 40, 4107402, 0, 18, 20063115, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 1, "白熱！　格闘大会！", "カオリとの出会い", 8, "フリーマーケット会場");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118066, 91002, 2, 10118, 40, 9000227, 1, 16, 20063115, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 1, "祭り太鼓はオーエドの華", "ニノンとの出会い", 8, "オーエド町");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118067, 91002, 3, 10118, 40, 2101181, 0, 19, 20063115, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 1, "人気者は遅れて\nやってくる", "スズナとの出会い", 8, "フリーマーケット会場");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118068, 91002, 3, 10118, 40, 4109402, 0, 18, 20063115, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 1, "巫女・ミーツ・魔法少女", "ナナカとの出会い", 8, "ランドソル市街地");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118069, 91002, 3, 10118, 40, 4305402, 0, 18, 20063115, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 1, "ネズ耳は二度なくなる", "キャル＆コッコロとの出会い", 8, "フリーマーケット会場");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118070, 91002, 3, 10118, 40, 4101402, 0, 18, 20063115, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 1, "この出会いにカンパイ！", "ユカリとの出会い", 8, "ランドソル市街地");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118071, 91002, 3, 10118, 40, 4106402, 0, 18, 20063115, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 1, "陰陽アンサンブル", "アオイとの出会い", 8, "ランドソル市街地");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118072, 91002, 3, 10118, 40, 2836, 1, 7, 20063115, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 1, "運試し十番勝負！", "シノブとの出会い", 8, "フリーマーケット会場");
INSERT INTO `v1_41f94a19b851e580715426440886209ea112ef0fe9b2d326347b8afeaa76f5ec` VALUES (5118600, 0, 1, 10118, 0, 0, 0, 0, 20063115, 0, 0, "彼女たちの新たな日常", "オープニング", 0, 0);
